@echo off
title ReasonIX Launcher
echo ============================================
echo        Starting ReasonIX...
echo ============================================
echo.
REM Start ReasonIX code mode with web dashboard, skip interactive selection
REM Use --dashboard-port 8765 to avoid Chrome ERR_UNSAFE_PORT on default port 6667
reasonix code -n --open-dashboard --dashboard-port 8765
echo.
echo ============================================
echo        ReasonIX has stopped.
echo ============================================
pause

@echo off
"C:\Program Files\R\R-4.6.0\bin\x64\Rscript.exe" "%~dp0launch_biblioshiny.R"
pause
